// A complete public synthetic IPA, using the SINF inner key generated by
// syntheticCurrentSINFForPrecursorRights and syntheticSignedSUPF's fixed page
// record. The page key below was generated with the typed page-key algorithm;
// this fixture establishes integration, not independent/native crypto proof.
func snapshotIPAImage(t *testing.T, supf []byte) ([]byte, []byte) {
	t.Helper()
	const page = 4096
	const signatureBytes = 20 + 96 + 4*32
	blob := make([]byte, 2*page+signatureBytes)
	le := func(at int, v uint32) { binary.LittleEndian.PutUint32(blob[at:], v) }
	le(0, 0xfeedfacf)
	le(4, 0x0100000c)
	le(12, 2)
	le(16, 2)
	le(20, 40)
	le(32, 0x2c)
	le(36, 24)
	le(40, page)
	le(44, page)
	le(48, 1)
	le(56, 0x1d)
	le(60, 16)
	le(64, 2*page)
	le(68, signatureBytes)
	plain := bytes.Repeat([]byte{0x1f, 0x20, 0x03, 0xd5}, page/4)
	copy(blob[page:2*page], plain)
	sig := blob[2*page:]
	binary.BigEndian.PutUint32(sig, 0xfade0cc0)
	binary.BigEndian.PutUint32(sig[4:], signatureBytes)
	binary.BigEndian.PutUint32(sig[8:], 1)
	binary.BigEndian.PutUint32(sig[16:], 20)
	dir := sig[20:]
	be := func(at int, v uint32) { binary.BigEndian.PutUint32(dir[at:], v) }
	be(0, 0xfade0c02)
	be(4, uint32(len(dir)))
	be(8, 0x20500)
	be(16, 96)
	be(28, 2)
	be(32, 2*page)
	be(92, 160)
	dir[36], dir[37], dir[39] = 32, 2, 12
	for slot := range 2 {
		hash := sha256.Sum256(blob[slot*page : (slot+1)*page])
		copy(dir[160+32*slot:], hash[:])
	}
	key := [16]byte{0xc1, 0x7a, 0x5b, 0x85, 0x09, 0x35, 0x27, 0x73, 0xf0, 0x62, 0x55, 0xf3, 0xf4, 0x5c, 0x76, 0xf7}
	block, err := aes.NewCipher(key[:])
	if err != nil {
		t.Fatal(err)
	}
	cipher.NewCBCEncrypter(block, supf[44:60]).CryptBlocks(blob[page:2*page], plain)
	for slot := range 2 {
		hash := sha256.Sum256(blob[slot*page : (slot+1)*page])
		copy(dir[96+32*slot:], hash[:])
	}
	return blob, plain
}

func writeSnapshotIPA(t *testing.T, name string, blob, sinf, supf []byte) {
	t.Helper()
	f, err := os.Create(name)
	if err != nil {
		t.Fatal(err)
	}
	w := zip.NewWriter(f)
	for _, member := range []struct {
		name string
		data []byte
	}{
		{"Payload/Test.app/Test", blob}, {"Payload/Test.app/SC_Info/Test.sinf", sinf}, {"Payload/Test.app/SC_Info/Test.v5.supf", supf},
	} {
		out, err := w.Create(member.name)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := out.Write(member.data); err != nil {
			t.Fatal(err)
		}
	}
	if err := w.Close(); err != nil {
		t.Fatal(err)
	}
	if err := f.Close(); err != nil {
		t.Fatal(err)
	}
}

func TestSnapshotIPAEndToEnd(t *testing.T) {
	snapshot, sinf, _ := syntheticSnapshotRecovery(t)
	defer snapshot.Clear()
	supf, authority := syntheticSignedSUPF(t, 5)
	blob, plain := snapshotIPAImage(t, supf)
	dir := t.TempDir()
	ipa := filepath.Join(dir, "input.ipa")
	writeSnapshotIPA(t, ipa, blob, sinf, supf)
	licenses, err := fairplay.ReadIPAEnrollmentInputs(ipa)
	if err != nil {
		t.Fatal(err)
	}
	defer licenses.Clear()
	inputs, err := snapshotRecoveryInputs(snapshot, licenses)
	if err != nil {
		t.Fatal(err)
	}
	// This package-local test seam retains signed-envelope verification using
	// the synthetic CA; public entry points always use the pinned authority.
	recovered, err := recoverCurrentInputs(context.Background(), inputs, nil, authority)
	if err != nil {
		t.Fatal(err)
	}
	defer clear(recovered.EnrollmentModel)
	model := filepath.Join(dir, "model.bin")
	if err := os.WriteFile(model, recovered.EnrollmentModel, 0600); err != nil {
		t.Fatal(err)
	}
	decrypt := func(name string) (fairplay.DecryptResult, error) {
		return fairplay.DecryptIPA(fairplay.DecryptOptions{InputPath: ipa, ModelPath: model, OutputPath: filepath.Join(dir, name+".ipa"), ReportPath: filepath.Join(dir, name+".json")})
	}
	result, err := decrypt("valid")
	if err != nil {
		t.Fatal(err)
	}
	if !result.PlaintextVerified || result.EncryptedImages != 1 || result.DecryptedPages != 1 {
		t.Fatal("incomplete IPA validation")
	}
	archive, err := zip.OpenReader(result.OutputPath)
	if err != nil {
		t.Fatal(err)
	}
	found := false
	for _, f := range archive.File {
		if f.Name != "Payload/Test.app/Test" {
			continue
		}
		r, err := f.Open()
		if err != nil {
			t.Fatal(err)
		}
		out, err := io.ReadAll(r)
		r.Close()
		if err != nil {
			t.Fatal(err)
		}
		if !bytes.Equal(out[4096:8192], plain) || binary.LittleEndian.Uint32(out[48:52]) != 0 {
			t.Fatal("incorrect plaintext")
		}
		found = true
	}
	archive.Close()
	if !found {
		t.Fatal("missing output executable")
	}
	// A self-consistent ciphertext hash cannot substitute for plaintext hashes.
	wrong := bytes.Clone(blob)
	wrong[4096] ^= 1
	hash := sha256.Sum256(wrong[4096:8192])
	copy(wrong[8192+20+96+32:], hash[:])
	writeSnapshotIPA(t, ipa, wrong, sinf, supf)
	if _, err := decrypt("wrong"); err == nil {
		t.Fatal("accepted wrong plaintext")
	}
	if _, err := os.Stat(filepath.Join(dir, "wrong.ipa")); !os.IsNotExist(err) {
		t.Fatal("published invalid IPA")
	}
	missing := bytes.Clone(blob)
	binary.BigEndian.PutUint32(missing[8192+20+92:], 0)
	writeSnapshotIPA(t, ipa, missing, sinf, supf)
	result, err = decrypt("unverified")
	if err != nil || result.PlaintextVerified {
		t.Fatal("missing hashes were treated as verified", err)
	}
}
